head.script:
/************************************************************************************
 * ID           :	ULDSTF08200
 * File         :	ULDSTF08200.xml
 * Name         :	ETN 마감
 * Description  :	(as-is) 아래 화면을 탭으로 통합
 *                    [신규상장 마감]     ULDSTF08200.gfm  ETN 마감처리 / 마감처리내역 (조회구분으로 전환)
 *                    [투자유의종목 마감] ULDSTF08311.gfm  ETN 투자유의종목 마감
 *                                        + ULDSTF08306.gfm 기능(목록 더블클릭 상세, 단계별 신규등록)
 * Create Date  :	2026-10-23
************************************************************************************/

///////// 1. 변수 및 선언 영역 /////////

scwin.SECUGRP_ID = "EN";                 // 증권그룹ID (ETN)
scwin.ISU_TP_CD = "ETN";                 // 종목유형코드 (마감이력 조회용)
scwin.SECUGRP_NM = "ETN";                // 증권그룹명 (팝업 제목용 — 공통 getSecuGrpNm 에 EN 매핑 없음)

scwin.jobTitl = "";                      // 직책 (03: 담당자, 그 외: 팀장)
scwin.depCd = "";                        // 부서코드 (ZSYS: 시스템관리자 → 재마감 가능)
scwin.mktId = "";                        // 시장구분코드
scwin.todayDd = "";                      // 서버 현재일 (yyyyMMdd)
scwin.procJob = "";                      // 진행중인 처리명 (메시지용)

// [신규상장 마감]
scwin.TAB_NEW = 0;
scwin.newIsHist = false;                 // true: 마감처리내역(전송내역), false: 마감처리 대상
// 마감처리내역(전송내역) 응답 필드 → 마감처리 그리드 컬럼 (같은 그리드에 보이도록 맞춘다)
scwin.HIST_TO_PROC = {
    ordSpdUplmtVal: "declSpd",              // 호가스프레드 상한값
    isuPrc: "etnIsuPrc",                    // 발행가격
    etnEarngStructId: "earngStructTpCd",    // 수익구조ID
    etnEarngStructContn: "expEarngStructDscVal",
    etnMaxRedmptPrc: "expMaxRedmptPrc",
    etnMinRedmptPrc: "expMinRedmptPrc",
    etnEaryRedmptPosblYn: "earyRedmptCondYn",
    etnEaryRedmptCycleNm: "earyRedmptCycleNm",
    valuPrcCalcInstNm1: "valuPrc1CalcInstNm",
    valuPrcCalcInstNm2: "valuPrc2CalcInstNm"
};

// [투자유의종목 마감]
scwin.TAB_WARN = 1;
scwin.warnSearchDd = "";                 // 조회한 마감일 (마감처리 시 조회일과 같은지 확인)
scwin.warnLoaded = false;                // 5개 목록 조회 완료 여부
scwin.warnCalDd = "";                    // 마감일의 다음 영업일 (투자유의 지정일 기본값, ASIS cal_dd)
scwin.isWarnFirst = true;                // 투자유의종목 마감 탭 최초 진입 여부

/**
 * 투자유의 단계 정의
 *  key        : 단계 키 (그리드 grd_Warn{key}, 데이터 dlt_warn{key}, 건수 txb_cnt{key})
 *  name       : 단계명
 *  nowAction  : 당일 조회 API
 *  histCd     : 마감이력 조회 ETP투자유의코드
 *  reqKey     : 팀장승인/재마감 요청 리스트 키
 *  popup      : 상세(신규/수정) 팝업 (ASIS ULDSTF08306 에서 열던 화면)
 *  canRegist  : [신규] 가능 여부 (ASIS 지정예고 탭은 신규 버튼 숨김)
 */
scwin.WARN_STEPS = [
    { key: "2", name: "지정예고", nowAction: "/api/listing/lstproc/etn/close-procs-invst-warn/select-list-noti",     histCd: "0A", reqKey: "clsIsuNoti",    popup: { id: "ULDSTF08307", nm: " 투자유의종목 지정예고" }, canRegist: false },
    { key: "3", name: "지정연장", nowAction: "/api/listing/lstproc/etn/close-procs-invst-warn/select-list-extn",     histCd: "04", reqKey: "clsIsuExtn",    popup: { id: "ULDSTF08304", nm: " 투자유의종목 지정연장" }, canRegist: true },
    { key: "4", name: "지정",     nowAction: "/api/listing/lstproc/etn/close-procs-invst-warn/select-list-design",   histCd: "03", reqKey: "clsIsuDesign",  popup: { id: "ULDSTF08303", nm: " 투자유의종목 지정" },     canRegist: true },
    { key: "5", name: "지정해제", nowAction: "/api/listing/lstproc/etn/close-procs-invst-warn/select-list-release",  histCd: "05", reqKey: "clsIsuRelease", popup: { id: "ULDSTF08305", nm: " 지정해제" },              canRegist: true },
    { key: "6", name: "매매거래정지", nowAction: "/api/listing/lstproc/etn/close-procs-invst-warn/select-list-trd-halt", histCd: "06", reqKey: "clsIsuTrdHalt", popup: null,                                        canRegist: true }
];

// 매매거래정지 팝업 (0: 지정, 1: 해제, 2: 지정및해제, 3: 지정→해제)
scwin.TRD_HALT_POPUP = {
    "0": { id: "ULDSTF08043", nm: " 매매거래정지 지정" },
    "1": { id: "ULDSTF08044", nm: " 매매거래정지 해제" },
    "2": { id: "ULDSTF08042", nm: " 매매거래정지 지정 및 해제" },
    "3": { id: "ULDSTF08044", nm: " 매매거래정지 해제" }
};

// ETP투자유의지정코드 → 거래정지지정및해제구분 (06: 정지, 07: 해제, 08: 정지및해제)
scwin.HALT_TP_BY_DESIGN_CD = { "06": "0", "07": "1", "08": "2" };

// 매매거래정지 신규 기본 문구 (ASIS fn_GetParNewTrdHalt)
scwin.TRD_HALT_REMK = {
    "0": "상기 종목은 시장상황급변 등으로 투자자보호 및 시장안정을 위하여 매매거래가 정지됩니다.\r\n" +
         "매매거래정지 해제 시 별도의 시장안내가 있을 예정이며,\r\n" +
         "매매거래 재개시 투자유의종목으로서 3매매거래일(지정단위기간) 단위의 단일가매매로 거래가 재개됩니다.",
    "1": "상기 종목은 매매거래정지 사유가 해소됨에 따라 매매거래정지가 해제되며,\r\n" +
         "매매거래정지해제일부터 투자유의종목으로서 3매매거래일(지정단위기간) 단위의 단일가매매로 거래가 재개됩니다.",
    "2": "상기 종목은 투자유의종목 지정단위기간(3매매거래일)이 종료하는 날에 장종료시 실시간 괴리율이\r\n" +
         "규정상 의무범위의 3배 이상에 해당하여 1일간 매매거래가 정지됩니다.\r\n" +
         "매매거래정지해제일부터는 지정단위기간이 새롭게 시작되며, 단일가 매매로 거래가 재개됩니다\r\n\r\n" +
         "※ 시장상황급변 등 투자자보호 및 시장안정을 위해 매매거래정지 기간은 연장될 수 있습니다."
};


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @description 페이지로드
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.onpageload" });
    }
};

scwin.onpageunload = function () {
};

/**
 * @method
 * @name scwin.init
 * @description 초기화. 담당자·팀장 버튼은 마감정보 조회 후 상태를 정하므로 먼저 잠근다. (ASIS gform onload)
 * @hidden N
*/
scwin.init = async function () {
    // inputCalendar validate
    $c.date.checkCalendarFormat(edt_TASK_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_LIST_DD, "yyyyMMdd");
    $c.date.checkCalendarFormat(edt_ConfirmDate, "yyyyMMdd");

    scwin.jobTitl = $c.session.getUserInfo("jobtitl") ?? "";
    scwin.depCd = $c.session.getUserInfo("depCd") ?? "";
    scwin.mktId = $c.session.getUserInfo("market") ?? "";
    scwin.todayDd = $c.date.getServerDateTime("yyyyMMdd");

    // 재마감처리는 시스템관리자만
    scwin.setReclsButton(btn_Recls);
    scwin.setReclsButton(btn_WarnRecls);

    btn_Revw.setDisabled(true);
    btn_Cls.setDisabled(true);
    btn_WarnRevw.setDisabled(true);
    btn_WarnAprv.setDisabled(true);

    edt_TASK_DD.setValue(scwin.todayDd);

    MaxTab_01.setSelectedTabIndex(scwin.TAB_NEW);
    await scwin.newListSync();
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.MaxTab_01_onchange
 * @description 탭 변경. 선택한 탭을 다시 조회한다.
 * @hidden N
*/
scwin.MaxTab_01_onchange = async function (tabId, index) {
    try {
        if (MaxTab_01.getSelectedTabIndex() === scwin.TAB_WARN) {
            if (scwin.isWarnFirst) {
                edt_ConfirmDate.setValue(scwin.todayDd);
                scwin.isWarnFirst = false;
            }
            await scwin.warnListSync();
        } else {
            await scwin.newListSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.MaxTab_01_onchange" });
    }
};

/**
 * @event
 * @name scwin.btn_ProcExcel_onclick
 * @description 엑셀다운로드 (선택한 탭 기준)
 * @hidden N
*/
scwin.btn_ProcExcel_onclick = async function () {
    try {
        if (MaxTab_01.getSelectedTabIndex() === scwin.TAB_WARN) {
            await scwin.warnExcelDown();
        } else {
            await scwin.newExcelDown();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_ProcExcel_onclick" });
    }
};

// ----- [신규상장 마감] -----

scwin.btn_Search_onclick = async function () {
    try {
        await scwin.newListSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_Search_onclick" });
    }
};



/**
 * @event
 * @name scwin.grd_New_Proc_oncellclick
 * @description 신규상장 행 클릭 시 상환주기를 조회한다.
 *  마감처리 대상은 업무처리번호로(ASIS fn_SearchRedmpt), 마감처리내역은 종목코드로(ASIS fn_SearchRedmptRv) 조회한다.
 * @hidden N
*/
scwin.grd_New_Proc_oncellclick = async function (row, col, colId) {
    try {
        if (row < 0) return;
        if (scwin.newIsHist) {
            await scwin.searchRedmptHist(dlt_newProc.getCellData(row, "isuCd"));
        } else {
            await scwin.searchRedmpt(dlt_newProc.getCellData(row, "bzProcsNo"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.grd_New_Proc_oncellclick" });
    }
};



scwin.btn_Recls_onclick = async function () {
    try {
        await scwin.newRecls();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_Recls_onclick" });
    }
};

scwin.btn_Revw_onclick = async function () {
    try {
        await scwin.newRevw();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_Revw_onclick" });
    }
};

scwin.btn_Cls_onclick = async function () {
    try {
        await scwin.newCls();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_Cls_onclick" });
    }
};

// ----- [투자유의종목 마감] -----

scwin.btn_WarnSearch_onclick = async function () {
    try {
        await scwin.warnListSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_WarnSearch_onclick" });
    }
};

scwin.btn_WarnRevw_onclick = async function () {
    try {
        await scwin.warnRevw();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_WarnRevw_onclick" });
    }
};

scwin.btn_WarnAprv_onclick = async function () {
    try {
        await scwin.warnAprv();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_WarnAprv_onclick" });
    }
};

scwin.btn_WarnRecls_onclick = async function () {
    try {
        await scwin.warnRecls();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_WarnRecls_onclick" });
    }
};

// 단계별 [신규] (ASIS ULDSTF08306 img_Regist)
scwin.btn_WarnNew3_onclick = async function () {
    try {
        await scwin.warnRegist("3");
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_WarnNew3_onclick" });
    }
};
scwin.btn_WarnNew4_onclick = async function () {
    try {
        await scwin.warnRegist("4");
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_WarnNew4_onclick" });
    }
};
scwin.btn_WarnNew5_onclick = async function () {
    try {
        await scwin.warnRegist("5");
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_WarnNew5_onclick" });
    }
};
scwin.btn_WarnNew6_onclick = async function () {
    try {
        await scwin.warnRegist("6");
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.btn_WarnNew6_onclick" });
    }
};

// 단계별 목록 더블클릭 (ASIS ULDSTF08306 grd_2~6 OnDblClick)
scwin.grd_Warn2_oncelldblclick = async function (row) {
    try {
        await scwin.warnOpenDetail("2", row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.grd_Warn2_oncelldblclick" });
    }
};
scwin.grd_Warn3_oncelldblclick = async function (row) {
    try {
        await scwin.warnOpenDetail("3", row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.grd_Warn3_oncelldblclick" });
    }
};
scwin.grd_Warn4_oncelldblclick = async function (row) {
    try {
        await scwin.warnOpenDetail("4", row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.grd_Warn4_oncelldblclick" });
    }
};
scwin.grd_Warn5_oncelldblclick = async function (row) {
    try {
        await scwin.warnOpenDetail("5", row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.grd_Warn5_oncelldblclick" });
    }
};
scwin.grd_Warn6_oncelldblclick = async function (row) {
    try {
        await scwin.warnOpenDetail("6", row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.grd_Warn6_oncelldblclick" });
    }
};


///////// 4. 서브미션 영역 /////////

// ===== [신규상장 마감] (ASIS ULDSTF08200.gfm) =====

/**
 * @method
 * @name scwin.newListSync
 * @description 신규상장 마감 조회. 상장일·마감정보를 읽은 뒤 마감일·팀장승인 여부에 따라 마감처리 대상 또는 마감처리내역을 조회한다.
 *  ASIS fn_list_sync
 * @hidden N
*/
scwin.newListSync = async function () {
    const taskDd = edt_TASK_DD.getValue();
    if ($c.util.isEmpty(taskDd) || taskDd.length < 8) {
        await $c.win.alert("마감일을 입력하세요.");
        edt_TASK_DD.focus();
        return;
    }
    // 상장일 (마감일의 다음 영업일)
    edt_LIST_DD.setValue("");
    let result = await $c.sbm.executeDynamic({
        id: "sbm_newNextBzDay",
        method: "get",
        action: "/api/listing/lstproc/etn/close-procs-newlisting/next-bz-day",
        isProcessMsg: false
    }, { taskDd: taskDd });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (result.responseJSON?.success) {
        edt_LIST_DD.setValue(result.responseJSON.body?.listDd ?? "");
    }

    // 마감이력 (담당자·팀장·전송시각)
    dma_clsInfo.setEmptyValue();
    await $c.sbm.executeDynamic({
        id: "sbm_newClsInfo",
        method: "get",
        action: "/api/listing/lstproc/etn/close-procs-newlisting/close-info",
        target: "dma_clsInfo=body",
        isProcessMsg: false
    }, { taskDd: taskDd, isuTpCd: scwin.ISU_TP_CD });

    // 마감일이 당일이고 팀장 승인 전이면 마감처리 대상을, 마감일이 당일이 아니거나 팀장 승인 후면 마감처리내역(전송내역)을 보여 준다.
    scwin.newIsHist = (taskDd !== scwin.todayDd) || !$c.util.isEmpty(dma_clsInfo.get("bzClsTm"));
    scwin.applyNewMode();

    if (scwin.newIsHist) {
        await scwin.searchNewHist();
    } else {
        await scwin.searchNewProc();
    }
    scwin.setNewButtonState();
};

/**
 * @method
 * @name scwin.searchNewProc
 * @description 마감처리 대상(상장일 기준 신규상장)을 조회하고 첫 건의 상환주기를 조회한다.
 * @hidden N
*/
scwin.searchNewProc = async function () {
    dlt_newProc.removeAll();
    dlt_addProc.removeAll();

    const result = await $c.sbm.executeDynamic({
        id: "sbm_newProc",
        method: "get",
        action: "/api/listing/lstproc/etn/close-procs-newlisting/select-list",
        target: "dlt_newProc=body",
        isProcessMsg: false
    }, { taskDd: edt_LIST_DD.getValue() });   // 조회조건은 상장일 (ASIS {P}param01=LIST_DD)
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    if (result.responseJSON?.success) {
        txb_New_Proc_TotalCnt.setValue(dlt_newProc.getRowCount());
        if (dlt_newProc.getRowCount() > 0) {
            await scwin.searchRedmpt(dlt_newProc.getCellData(0, "bzProcsNo"));
        } else {
            txb_Add_Proc_TotalCnt.setValue(0);
        }
    }
};

/**
 * @method
 * @name scwin.searchRedmpt
 * @description 신규상장 한 건의 상환주기를 조회한다. (ASIS fn_SearchRedmpt)
 * @hidden N
*/
scwin.searchRedmpt = async function (bzProcsNo) {
    dlt_addProc.removeAll();
    txb_Add_Proc_TotalCnt.setValue(0);
    if ($c.util.isEmpty(bzProcsNo)) return;

    const result = await $c.sbm.executeDynamic({
        id: "sbm_addProc",
        method: "get",
        action: "/api/listing/lstproc/etn/close-procs-newlisting/select-list-redemption",
        target: "dlt_addProc=body",
        isProcessMsg: false
    }, { bzProcsNo: bzProcsNo }, null, { onDuplicate: "abort" });

    if (result.responseJSON?.success) {
        txb_Add_Proc_TotalCnt.setValue(dlt_addProc.getRowCount());
    }
};

/**
 * @method
 * @name scwin.searchNewHist
 * @description 마감처리내역(전송내역)과 상환주기 전송내역 전체를 조회한다. (ASIS ETN마감처리내역 탭)
 *  응답 필드명을 마감처리 그리드 컬럼명으로 바꿔 같은 그리드에 담는다.
 * @hidden N
*/
scwin.searchNewHist = async function () {
    dlt_newProc.removeAll();

    const result = await $c.sbm.executeDynamic({
        id: "sbm_newHist",
        method: "get",
        action: "/api/listing/lstproc/etn/close-procs-newlisting/select-list-hist",
        isProcessMsg: false
    }, { taskDd: edt_TASK_DD.getValue() });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    if (result.responseJSON?.success) {
        dlt_newProc.setJSON((result.responseJSON.body ?? []).map(scwin.toProcRow));
    }
    txb_New_Proc_TotalCnt.setValue(dlt_newProc.getRowCount());

    await scwin.searchRedmptHist("");
};

/**
 * @method
 * @name scwin.searchRedmptHist
 * @description 상환주기 전송내역. 종목코드가 없으면 마감일 전체. (ASIS fn_SearchRedmptRv / redmpt.rv.all)
 * @hidden N
*/
scwin.searchRedmptHist = async function (isuCd) {
    dlt_addProc.removeAll();

    const result = await $c.sbm.executeDynamic({
        id: "sbm_addHist",
        method: "get",
        action: "/api/listing/lstproc/etn/close-procs-newlisting/select-list-redemption-hist",
        target: "dlt_addProc=body",
        isProcessMsg: false
    }, { taskDd: edt_TASK_DD.getValue(), isuCd: isuCd ?? "" }, null, { onDuplicate: "abort" });

    txb_Add_Proc_TotalCnt.setValue(result.responseJSON?.success ? dlt_addProc.getRowCount() : 0);
};

/**
 * @method
 * @name scwin.postClose
 * @description 마감 처리 공통 전송. 성공하면 완료 안내 후 다시 조회한다.
 * @param {String} action API 경로
 * @param {Object} requestData 요청 본문
 * @param {Function} afterFn 성공 후 재조회 함수
 * @hidden N
*/
scwin.postClose = async function (action, requestData, afterFn) {
    const result = await $c.sbm.executeDynamic({
        id: "sbm_close",
        method: "post",
        action: action,
        mediatype: "application/json",
        isProcessMsg: false
    }, requestData);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (result.responseJSON?.success && result.responseJSON.body?.completeYn === true) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.procJob));
        await afterFn();
    } else {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.procJob));
    }
};


///////// 5. 일반/업무 함수 영역 /////////

// ===== [신규상장 마감] =====

/**
 * @method
 * @name scwin.applyNewMode
 * @description 마감처리 대상 / 마감처리내역에 맞춰 그리드 컬럼·제목·안내 문구를 바꾼다.
 *  - 마감처리 대상 : 신청일련번호·발행회사 표시
 *  - 마감처리내역  : 작업일자 표시, 상환주기는 작업일자·종목코드 표시
 * @hidden N
*/
scwin.applyNewMode = function () {
    const isHist = scwin.newIsHist;

    //txb_NewMode.setValue(isHist ? "마감처리내역" : "마감처리");

    grd_New_Proc.setColumnVisible("taskDd", isHist);
    grd_New_Proc.setColumnVisible("bzProcsNo", !isHist);
    grd_New_Proc.setColumnVisible("comNm", !isHist);

    grd_Add_Proc.setColumnVisible("taskDd", isHist);
    grd_Add_Proc.setColumnVisible("isuCd", isHist);
    grd_Add_Proc.setColumnVisible("bzProcsNo", !isHist);

    if (isHist) {
        txt_NewProcInfo.hide();
        txt_NewHistInfo.show("");
    } else {
        txt_NewProcInfo.show("");
        txt_NewHistInfo.hide();
    }
};

/** 마감처리내역 행의 필드명을 마감처리 그리드 컬럼명으로 바꾼다. */
scwin.toProcRow = function (row) {
    const out = { ...row };
    for (const [from, to] of Object.entries(scwin.HIST_TO_PROC)) {
        if (from in out) {
            out[to] = out[from];
            delete out[from];
        }
    }
    return out;
};

/**
 * @method
 * @name scwin.newRecls
 * @description 재마감처리 (시스템관리자). 이전 마감처리 기록을 지운다. (ASIS fn_recls)
 * @hidden N
*/
scwin.newRecls = async function () {
    scwin.procJob = "재마감처리";
    if (!await scwin.checkProcDt(scwin.procJob)) return;

    if (!await $c.win.confirm("재마감처리를 선택 하셨습니다.\n재마감처리는 이전마감처리기록을 삭제하므로\n재마감처리후 다시 마감처리를 하셔야 됩니다.\n\n재마감처리를 하시겠습니까?")) return;

    await scwin.postClose("/api/listing/lstproc/etn/close-procs-newlisting/reClose", {}, scwin.newListSync);
};

/**
 * @method
 * @name scwin.newRevw
 * @description 담당자 확인. (ASIS fn_revw)
 * @hidden N
*/
scwin.newRevw = async function () {
    scwin.procJob = "담당자 확인";
    if (!await scwin.checkProcDt(scwin.procJob)) return;

    if (!await $c.win.confirm("담당자 확인 하시겠습니까?")) return;

    await scwin.postClose("/api/listing/lstproc/etn/close-procs-newlisting/revwFinal", {}, scwin.newListSync);
};

/**
 * @method
 * @name scwin.newCls
 * @description 팀장승인(마감처리). 담당자 확인 후에만 가능하다. (ASIS fn_cls)
 * @hidden N
*/
scwin.newCls = async function () {
    if ($c.util.isEmpty(dma_clsInfo.get("approvTm"))) {
        await $c.win.alert("담당자가 확인하지 않았습니다. 담당자 확인 후 마감처리를 해주십시오.");
        return;
    }

    scwin.procJob = "마감처리";
    const listDd = edt_LIST_DD.getValue();
    if ($c.util.isEmpty(listDd)) {
        await $c.win.alert("[상장일]이 없습니다.");
        edt_LIST_DD.focus();
        return;
    }

    if (!await $c.win.confirm("마감처리 하시겠습니까?")) return;

    await scwin.postClose("/api/listing/lstproc/etn/close-procs-newlisting/apprvFinal", { listDd: listDd }, scwin.newListSync);
};

/**
 * @method
 * @name scwin.checkProcDt
 * @description 마감일이 당일인지, 발행시장참가자번호가 없는 종목이 없는지 확인한다. (ASIS fn_checkProcDt)
 * @hidden N
*/
scwin.checkProcDt = async function (str) {
    if (edt_TASK_DD.getValue() !== scwin.todayDd) {
        await $c.win.alert("[마감일]이 현재일경우만 '" + str + "'를 할수 있습니다.");
        return false;
    }

    for (let i = 0; i < dlt_newProc.getRowCount(); i++) {
        if ($c.util.isEmpty(dlt_newProc.getCellData(i, "isuMktpartcNo"))) {
            await $c.win.alert("발행회사명에 대한 시장참가자번호가 없는 종목이 있습니다. 시스템관리자에게 문의바랍니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name scwin.setNewButtonState
 * @description 담당자확인·팀장승인 버튼 상태. (ASIS buttonSetDis)
 *  - 마감일이 당일이 아님     : 둘 다 잠금
 *  - 팀장 확인(마감) 완료     : 둘 다 잠금
 *  - 담당자 확인 전           : [담당자확인]만
 *  - 담당자 확인 후           : 담당자는 둘 다 잠금, 팀장은 [팀장승인]만
 * @hidden N
*/
scwin.setNewButtonState = function () {
    const isClosed = !$c.util.isEmpty(dma_clsInfo.get("bzClsTm"));
    const isReviewed = !$c.util.isEmpty(dma_clsInfo.get("approvEmpNm"));
    const isChrg = scwin.jobTitl === "03";
    const isPast = edt_TASK_DD.getValue() !== scwin.todayDd;

    btn_Revw.setDisabled(isPast || isClosed || isReviewed);
    btn_Cls.setDisabled(isPast || isClosed || !isReviewed || isChrg);

    scwin.setReclsButton(btn_Recls);
};

/**
 * @method
 * @name scwin.newExcelDown
 * @description 신규상장·상환주기 목록 엑셀다운로드 (마감처리 / 마감처리내역)
 * @hidden N
*/
scwin.newExcelDown = async function () {
    const today = $c.date.getServerDateTime("yyyyMMddHHmmss");
    const excelInfo = scwin.newIsHist
        ? [{ gridId: "grd_New_Proc", list: dlt_newProc, sheetName: "신규상장 송신목록" },
           { gridId: "grd_Add_Proc", list: dlt_addProc, sheetName: "상환주기 송신목록" }]
        : [{ gridId: "grd_New_Proc", list: dlt_newProc, sheetName: "신규상장 마감처리목록" },
           { gridId: "grd_Add_Proc", list: dlt_addProc, sheetName: "상환주기 마감처리목록" }];

    await scwin.downloadSheets("ULDSTF08200_ETN 신규상장 마감_" + today, excelInfo);
};

// ===== [투자유의종목 마감] (ASIS ULDSTF08311.gfm + ULDSTF08306.gfm) =====

/**
 * @method
 * @name scwin.warnListSync
 * @description 투자유의종목 마감 조회. (ASIS ULDSTF08311 fn_list_sync)
 *  마감일이 당일이 아니거나 팀장 승인이 끝났으면 마감이력(OLD)을, 아니면 당일 대상(NOW)을 조회한다.
 * @hidden N
*/
scwin.warnListSync = async function () {
    const trdDd = edt_ConfirmDate.getValue();
    if ($c.util.isEmpty(trdDd) || trdDd.length < 8) {
        await $c.win.alert("마감일을 입력하세요.");
        edt_ConfirmDate.focus();
        return;
    }

    scwin.warnLoaded = false;

    // 진행 중인 조회가 있으면 그쪽이 끝까지 처리한다.
    if (!await scwin.searchWarnFinalLog(trdDd)) return;

    // 마감일이 오늘이 아니거나 팀장 마감이 끝났으면 이력조회
    const isOld = (trdDd !== scwin.todayDd) || !$c.util.isEmpty(dma_warnLog.get("approvTeamleadrEmpNm"));
    scwin.warnSearchDd = trdDd;

    await scwin.searchMdClsCheck();
    await scwin.searchWarnCalDd(trdDd);

    for (const step of scwin.WARN_STEPS) {
        await scwin.searchWarnStep(step, trdDd, isOld);
    }

    scwin.warnLoaded = true;
    await scwin.checkDupList();
};

/**
 * @method
 * @name scwin.searchWarnStep
 * @description 투자유의 단계 한 개의 목록을 조회한다. (ASIS fn_list_dtl)
 * @hidden N
*/
scwin.searchWarnStep = async function (step, trdDd, isOld) {
    const list = scwin.getWarnComp(step.key).list;
    list.removeAll();

    const sbmOptions = {
        id: "sbm_warn" + step.key,
        method: "get",
        action: isOld ? "/api/listing/lstproc/etn/close-procs-invst-warn/select-list-hist" : step.nowAction,
        target: "dlt_warn" + step.key + "=body",
        isProcessMsg: false
    };
    const requestData = isOld ? { trdDd: trdDd, etpInvstwarnCd: step.histCd } : { trdDd: trdDd };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
    }

    scwin.getWarnComp(step.key).cnt.setValue(list.getRowCount());
};

/**
 * @method
 * @name scwin.searchWarnFinalLog
 * @description 담당자·팀장 마감 이력. 조회 후 버튼 상태를 정한다. (ASIS fn_clslog_sync)
 * @returns {Promise<Boolean>} 조회 진행 여부 — 중복 실행으로 건너뛰면 false
 * @hidden N
*/
scwin.searchWarnFinalLog = async function (trdDd) {
    dma_warnLog.setEmptyValue();

    const result = await $c.sbm.executeDynamic({
        id: "sbm_warnFinalLog",
        method: "get",
        action: "/api/listing/lstproc/etn/close-procs-invst-warn/select-final-log",
        target: "dma_warnLog=body",
        isProcessMsg: false
    }, { trdDd: trdDd });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    scwin.setWarnButtonState();
    return true;
};

/**
 * @method
 * @name scwin.searchMdClsCheck
 * @description 시장정보 배치실행 여부 (당일 기준). (ASIS getJungBoBatch)
 * @hidden N
*/
scwin.searchMdClsCheck = async function () {
    txb_ClsDtl.setValue("");

    const result = await $c.sbm.executeDynamic({
        id: "sbm_mdClsCheck",
        method: "get",
        action: "/api/listing/lstproc/etn/close-procs-invst-warn/md-close-check",
        isProcessMsg: false
    }, { trdDd: scwin.todayDd });

    if (result.responseJSON?.success) {
        txb_ClsDtl.setValue(result.responseJSON.body?.clsYn ?? "");
    }
};

/**
 * @method
 * @name scwin.searchWarnCalDd
 * @description 마감일의 다음 영업일. 상세 팝업의 지정일 기본값으로 쓴다. (ASIS ULDSTF08306 fn_cal_dd)
 * @hidden N
*/
scwin.searchWarnCalDd = async function (trdDd) {
    scwin.warnCalDd = "";

    const result = await $c.sbm.executeDynamic({
        id: "sbm_warnCalDd",
        method: "get",
        action: "/api/listing/lstproc/etn/close-procs-newlisting/next-bz-day",
        isProcessMsg: false
    }, { taskDd: trdDd });

    if (result.responseJSON?.success) {
        scwin.warnCalDd = result.responseJSON.body?.listDd ?? "";
    }
};

/**
 * @method
 * @name scwin.chkIsClose
 * @description 당일 마감일로 조회한 경우에만 마감할 수 있다. (ASIS chkIsClose)
 * @hidden N
*/
scwin.chkIsClose = async function () {
    if (edt_ConfirmDate.getValue() !== scwin.todayDd || scwin.warnSearchDd !== scwin.todayDd) {
        await $c.win.alert("당일날짜만 마감가능합니다. 마감일을 확인하세요");
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.warnRevw
 * @description 담당자 확인 마감. (ASIS fn_revw)
 * @hidden N
*/
scwin.warnRevw = async function () {
    scwin.procJob = "담당자 확인";
    if (!await scwin.chkIsClose()) return;
    if (!await $c.win.confirm(scwin.procJob + " 마감처리 하시겠습니까?")) return;

    await scwin.postClose("/api/listing/lstproc/etn/close-procs-invst-warn/revwFinal", {}, scwin.warnListSync);
};

/**
 * @method
 * @name scwin.warnAprv
 * @description 팀장 승인 마감. 조회한 단계별 목록을 함께 보낸다. (ASIS fn_aprv)
 * @hidden N
*/
scwin.warnAprv = async function () {
    if (!scwin.warnLoaded) {
        await $c.win.alert("데이터가 로딩중입니다. 로딩후에 승인가능합니다.");
        return;
    }
    if (!await scwin.chkIsClose()) return;

    scwin.procJob = "팀장승인";
    if ($c.util.isEmpty(dma_warnLog.get("chrgApprovTm"))) {
        await $c.win.alert("담당자확인 완료 후 승인처리 가능합니다.");
        return;
    }
    if (!await $c.win.confirm(scwin.procJob + " 마감처리 하시겠습니까?")) return;

    await scwin.postClose("/api/listing/lstproc/etn/close-procs-invst-warn/apprvFinal", scwin.getWarnCloseRequest(), scwin.warnListSync);
};

/**
 * @method
 * @name scwin.warnRecls
 * @description 투자유의 재마감처리 (시스템관리자). 팀장 승인 기록과 단계별 마감 종목을 지운다.
 * @hidden N
*/
scwin.warnRecls = async function () {
    scwin.procJob = "재마감처리";
    if (!scwin.warnLoaded) {
        await $c.win.alert("데이터가 로딩중입니다. 로딩후에 처리가능합니다.");
        return;
    }
    if (!await scwin.chkIsClose()) return;

    if (!await $c.win.confirm("재마감처리를 선택 하셨습니다.\n재마감처리는 이전마감처리기록을 삭제하므로\n재마감처리후 다시 마감처리를 하셔야 됩니다.\n\n재마감처리를 하시겠습니까?")) return;

    await scwin.postClose("/api/listing/lstproc/etn/close-procs-invst-warn/reclose", scwin.getWarnCloseRequest(), scwin.warnListSync);
};

/**
 * @method
 * @name scwin.getWarnCloseRequest
 * @description 팀장승인·재마감 요청 본문. 서버가 모든 리스트를 순회하므로 비어 있어도 빈 배열로 보낸다.
 *  최초적출(clsIsuFirstDetect)은 ASIS 에서도 조회하지 않고 빈 데이터셋(dts_List1)을 보냈다.
 * @hidden N
*/
scwin.getWarnCloseRequest = function () {
    const req = { clsIsuFirstDetect: [] };

    for (const step of scwin.WARN_STEPS) {
        req[step.reqKey] = scwin.getWarnComp(step.key).list.getAllJSON().map(row => ({
            isuCd: row.isuCd,
            etpInvstwarnDesignCd: row.etpInvstwarnDesignCd,
            fstDesignDd: row.fstDesignDd,
            designDd: row.designDd,
            releasDd: row.releasDd,
            bzProcsNo: row.bzProcsNo,
            addYn: row.addYn
        }));
    }
    return req;
};

/**
 * @method
 * @name scwin.setWarnButtonState
 * @description 담당자확인·팀장승인 버튼 상태. (ASIS ULDSTF08311 buttonSetDis)
 *  - 담당자 : 담당자 확인 전이면 [담당자확인]만, 확인 후면 둘 다 잠금
 *  - 팀장   : [담당자확인]은 담당자 확인 전만, [팀장승인]은 팀장 승인 전만
 * @hidden N
*/
scwin.setWarnButtonState = function () {
    const isReviewed = !$c.util.isEmpty(dma_warnLog.get("chrgApprovTm"));
    const isApproved = !$c.util.isEmpty(dma_warnLog.get("teamleadrApprovTm"));

    btn_WarnRevw.setDisabled(isReviewed);
    btn_WarnAprv.setDisabled(scwin.jobTitl === "03" ? true : isApproved);

    scwin.setReclsButton(btn_WarnRecls);
};

/**
 * @method
 * @name scwin.checkDupList
 * @description 단계별로 같은 종목이 두 번 들어 있으면 알린다. (ASIS checkDupList)
 * @hidden N
*/
scwin.checkDupList = async function () {
    for (const step of scwin.WARN_STEPS) {
        const isuCds = scwin.getWarnComp(step.key).list.getAllJSON().map(row => row.isuCd);
        if (new Set(isuCds).size !== isuCds.length) {
            await $c.win.alert("투자유의종목 " + step.name + " 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
        }
    }
};

/**
 * @method
 * @name scwin.warnRegist
 * @description 단계별 [신규]. 과거 마감일은 조회만 가능하다. (ASIS ULDSTF08306 img_Regist)
 * @param {String} key 단계 키
 * @hidden N
*/
scwin.warnRegist = async function (key) {
    try {
        const inqDd = edt_ConfirmDate.getValue();
        if (inqDd < scwin.todayDd) {
            await $c.win.alert("과거 조회일자인 경우 조회만 가능합니다.");
            return;
        }

        const ctx = { bzProcsNo: "", isuCd: "", isuNm: "", isurCd: "", isurNm: "", fstDtectDd: "", inqDd: inqDd, designDd: scwin.warnCalDd };

        if (key === "6") {
            const haltTpCd = sbx_RegistType.getValue();
            if ($c.util.isEmpty(haltTpCd) || haltTpCd === "(null)") {
                await $c.win.alert($c.data.getMessage("com_req_select", "신규등록구분"));
                sbx_RegistType.focus();
                return;
            }
            await scwin.openTrdHaltPopup(haltTpCd, scwin.getTrdHaltNewParam(ctx, haltTpCd));
            return;
        }

        const step = scwin.WARN_STEPS.find(s => s.key === key);
        await scwin.openWarnPopup(step, scwin.getWarnParam(ctx));
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.warnRegist" });
    }
};

/**
 * @method
 * @name scwin.warnOpenDetail
 * @description 단계별 목록 더블클릭. 업무처리번호가 있으면 수정, 없으면 신규로 상세 팝업을 연다.
 *  (ASIS ULDSTF08306 grd_2~6 OnDblClick)
 * @param {String} key 단계 키
 * @param {Number} row 행
 * @hidden N
*/
scwin.warnOpenDetail = async function (key, row) {
    try {
        if (row < 0) return;
        const list = scwin.getWarnComp(key).list;
        const ctx = {
            bzProcsNo: list.getCellData(row, "bzProcsNo") ?? "",
            isuCd: list.getCellData(row, "isuCd"),
            isuNm: list.getCellData(row, "isuKorNm"),
            isurCd: list.getCellData(row, "isurCd") ?? "",
            isurNm: list.getCellData(row, "isurNm") ?? "",
            fstDtectDd: list.getCellData(row, "fstDesignDd"),
            inqDd: edt_ConfirmDate.getValue(),
            designDd: scwin.warnCalDd
        };

        if (key !== "6") {
            const step = scwin.WARN_STEPS.find(s => s.key === key);
            await scwin.openWarnPopup(step, scwin.getWarnParam(ctx));
            return;
        }

        // 매매거래정지: ETP투자유의지정코드(06/07/08)로 정지/해제/정지및해제를 가른다.
        const haltTpCd = scwin.HALT_TP_BY_DESIGN_CD[list.getCellData(row, "etpInvstwarnDesignCd")] ?? "0";

        if (!$c.util.isEmpty(ctx.bzProcsNo)) {
            // 해제 건인데 정지일이 있으면 지정→해제(3)
            const popTp = (haltTpCd === "1" && !$c.util.isEmpty(list.getCellData(row, "designDd"))) ? "3" : haltTpCd;
            await scwin.openTrdHaltPopup(popTp, scwin.getTrdHaltUpdateParam(ctx, haltTpCd));
            return;
        }

        if (haltTpCd === "1") {
            // TODO: 종목해제 건은 원 정지 건의 업무처리번호를 찾아 해제 팝업으로 넘긴다.
            //       ASIS lds.stf.lstproc.etn.invstwarn.halt_desnrels_0.select (isuCd, fstDtectDd) — TO-BE API 미제공
            sbx_RegistType.setValue("1");
            await scwin.openTrdHaltPopup("1", scwin.getTrdHaltReleaseParam(ctx));
            return;
        }

        // 정지 건: 신규등록구분이 [지정]이 아니면 [지정 및 해제]로 연다.
        if (sbx_RegistType.getValue() !== "0") sbx_RegistType.setValue("2");
        const regTp = sbx_RegistType.getValue();
        await scwin.openTrdHaltPopup(regTp, scwin.getTrdHaltNewParam(ctx, regTp));
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF08200.warnOpenDetail" });
    }
};

/**
 * @method
 * @name scwin.getWarnParam
 * @description 투자유의 상세 팝업 파라미터. (ASIS fn_GetParNew / fn_GetParUpdate)
 * @hidden N
*/
scwin.getWarnParam = function (ctx) {
    return {
        isuCd: ctx.isuCd,
        isuNm: ctx.isuNm,
        secugrpId: scwin.SECUGRP_ID,
        fr_MktId: scwin.mktId,
        bzProcsNo: ctx.bzProcsNo,
        designDd: ctx.designDd,
        inqDd: ctx.inqDd,
        fstDtectDd: ctx.fstDtectDd,
        isurCd: ctx.isurCd
    };
};

/**
 * @method
 * @name scwin.getTrdHaltNewParam
 * @description 매매거래정지 신규 팝업 파라미터. (ASIS fn_GetParNewTrdHalt)
 * @hidden N
*/
scwin.getTrdHaltNewParam = function (ctx, haltTpCd) {
    return {
        isurCd: ctx.isurCd,
        isurNm: ctx.isurNm,
        secugrpId: scwin.SECUGRP_ID,
        fr_MktId: scwin.mktId,
        bzProcsNo: "",
        haltTpCd: haltTpCd,
        gubun: "",
        select_gubun: "3",                          // 선택 구분(1:종목, 2:발행회사, 3:전체)
        fstDtectDd: ctx.fstDtectDd,                 // 최초지정일
        designDd: ctx.designDd,                     // 매매거래정지일
        inqDd: ctx.inqDd,                           // 조회일
        arrRsn1: "302",
        arrRsn2: "투자유의종목(ETF, ETN)",
        arrRsn3: "유가증권시장 업무규정 제26조",
        remk: scwin.TRD_HALT_REMK[haltTpCd] ?? "",
        isuCd: ctx.isuCd,
        isuNm: ctx.isuNm
    };
};

