/**
 * @method
 * @name scwin.openWarnPopup
 * @description 투자유의 상세 팝업을 열고, 닫히면 목록을 다시 조회한다.
 *  ※ ETN 상세 팝업(ULDSTF08303/08304/08305/08307)은 전환본이 있으나 등록/수정 API 연결 전이다(삭제·조회만 동작).
 * @hidden N
*/
scwin.openWarnPopup = async function (step, param) {
    const opts = {
        id: step.popup.id,
        popupName: scwin.SECUGRP_NM + step.popup.nm,
        width: 800,
        height: 650,
        frameModal: "top",
        type: "pageFramePopup"
    };
    await $c.win.openPopup("/ui/lst/etn/" + step.popup.id + ".xml", opts, param);
    await scwin.warnListSync();
};

/**
 * @method
 * @name scwin.openTrdHaltPopup
 * @description 매매거래정지 팝업을 열고, 닫히면 목록을 다시 조회한다. 신규등록구분은 처음으로 되돌린다.
 *  ※ ETN 매매거래정지 팝업(ULDSTF08042/08043/08044)은 아직 TO-BE 전환 전이다.
 * @hidden N
*/
scwin.openTrdHaltPopup = async function (popTp, param) {
    const pop = scwin.TRD_HALT_POPUP[popTp];
    if (!pop) return;

    const opts = {
        id: pop.id,
        popupName: scwin.SECUGRP_NM + pop.nm,
        width: 850,
        height: 800,
        frameModal: "top",
        type: "pageFramePopup"
    };
    await $c.win.openPopup("/ui/lst/etn/" + pop.id + ".xml", opts, param);
    sbx_RegistType.setSelectedIndex(0);
    await scwin.warnListSync();
};

/**
 * @method
 * @name scwin.warnExcelDown
 * @description 투자유의 단계별 목록을 시트별로 한 파일에 받는다. (ASIS fn_ExcelDown)
 * @hidden N
*/
scwin.warnExcelDown = async function () {
    const today = $c.date.getServerDateTime("yyyyMMddHHmmss");
    const excelInfo = scwin.WARN_STEPS.map(step => ({
        gridId: "grd_Warn" + step.key,
        list: scwin.getWarnComp(step.key).list,
        sheetName: step.name
    }));

    await scwin.downloadSheets(today + "ETN투자유의종목마감", excelInfo);
};

// ===== 공통 =====

/** 투자유의 단계별 데이터·건수 컴포넌트 */
scwin.getWarnComp = function (key) {
    return {
        "2": { list: dlt_warn2, cnt: txb_cnt2 },
        "3": { list: dlt_warn3, cnt: txb_cnt3 },
        "4": { list: dlt_warn4, cnt: txb_cnt4 },
        "5": { list: dlt_warn5, cnt: txb_cnt5 },
        "6": { list: dlt_warn6, cnt: txb_cnt6 }
    }[key];
};

/** 재마감처리 버튼 — 시스템관리자(ZSYS)만 보인다. */
scwin.setReclsButton = function (btn) {
    if (scwin.depCd === "ZSYS") {
        btn.setDisabled(false);
        btn.show("");
    } else {
        btn.hide();
    }
};

/**
 * @method
 * @name scwin.downloadSheets
 * @description 데이터가 있는 그리드만 시트로 묶어 한 파일로 받는다.
 * @hidden N
*/
scwin.downloadSheets = async function (fileName, excelInfo) {
    const sheets = excelInfo
        .filter(info => info.list.getRowCount() > 0)
        .map(info => ({ gridId: info.gridId, sheetName: info.sheetName }));

    if (sheets.length === 0) {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
        return;
    }

    $c.data.downloadMultipleGridView({ common: { fileName: fileName + ".xlsx" }, excelInfo: sheets });
};
